mapper.select:
SELECT a.id, IFNULL(a.owner_name, 'unknown') AS owner_name,
       DATE_FORMAT(a.created_at, '%Y-%m-%d') AS created_text
FROM demo_asset a WHERE a.id = #{id}

SELECT a.id, COALESCE(a.owner_name, 'unknown') AS owner_name
FROM demo_asset a
WHERE a.status = #{status} AND a.tenant_code = #{tenantCode}

SELECT a.id, a.asset_name FROM demo_asset a WHERE a.status = 1
AND a.owner_id IN
#{ownerId}
